create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),order_number text not null unique,status text not null default 'pending' check(status in('pending','paid','cancelled','failed')),fulfilment_type text not null check(fulfilment_type in('collection','delivery')),fulfilment_status text not null default 'new',payment_status text not null default 'pending',stripe_payment_intent_id text unique,customer_name text not null,customer_email text not null,customer_phone text,collection_time text,delivery_address jsonb,delivery_notes text,subtotal_amount integer not null,delivery_fee_amount integer not null default 0,tax_amount integer not null default 0,total_amount integer not null,currency text not null default 'gbp',email_sent_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,menu_item_id text not null,item_name text not null,item_description text,unit_price_amount integer not null,quantity integer not null check(quantity>0),selected_options jsonb,special_instructions text,line_total_amount integer not null,created_at timestamptz not null default now());
alter table public.orders enable row level security;alter table public.order_items enable row level security;create policy "orders owner" on public.orders for select using(auth.uid()=user_id);create policy "order items owner" on public.order_items for select using(exists(select 1 from public.orders where id=order_id and user_id=auth.uid()));create index orders_user_created_idx on public.orders(user_id,created_at desc);create index order_items_order_idx on public.order_items(order_id);
